package com.cc91.repository;

import com.cc91.entity.Comment;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * 评论仓储接口
 */
@Repository
public interface CommentRepository extends JpaRepository<Comment, Long> {

    /**
     * 根据帖子ID查询所有评论（包括已删除的）
     */
    List<Comment> findByPostIdOrderByCreatedAtAsc(Long postId);

    /**
     * 根据帖子ID和状态查询评论
     */
    List<Comment> findByPostIdAndStatusOrderByCreatedAtAsc(Long postId, String status);

    /**
     * 根据父评论ID查询回复
     */
    List<Comment> findByParentIdOrderByCreatedAtAsc(Long parentId);

    /**
     * 统计帖子的所有评论数（包括子评论）
     */
    long countByPostId(Long postId);

    /**
     * 统计帖子的已发布评论数（包括子评论）
     */
    long countByPostIdAndStatus(Long postId, String status);

    /**
     * 查询某用户的评论（按时间倒序）
     */
    List<Comment> findByAuthorIdAndStatusOrderByCreatedAtDesc(Long authorId, String status);

    /**
     * 查询所有评论（按时间倒序，用于管理员审核）
     * JOIN FETCH 避免 LazyInitializationException
     */
    @Query("SELECT c FROM Comment c LEFT JOIN FETCH c.post LEFT JOIN FETCH c.author ORDER BY c.createdAt DESC")
    List<Comment> findAllWithPostAndAuthorByOrderByCreatedAtDesc();
}

